"""Opaque shared native object -> installed C/GObject SDK -> GI/Astra consumers."""
from pathlib import Path
import hashlib,json,os,shlex,subprocess,sys,tempfile
ROOT=Path(__file__).resolve().parents[2]
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def main(compiler_arg,output_arg):
	compiler=Path(compiler_arg).resolve();output=Path(output_arg).resolve();assert not output.is_relative_to(ROOT);output.mkdir(parents=True,exist_ok=True);work=Path(tempfile.mkdtemp(prefix='opaque-gobject-unit-',dir=output));here=Path(__file__).resolve().parent;importer=ROOT/'tools/gir/import.py';sources=[Path(__file__).resolve(),*[here/('gobject-unit'+suffix) for suffix in ['.astra','-support.c','-client.c','-gi.py','-profile.json','-roundtrip.astra.in','-roundtrip-client.c']],ROOT/'lib/runtime/interop/foreign-14.c',importer,importer.with_name('declarations.py')];receipt=dict(scope='opaque shared GObject SDK prerequisite; COM unit/signal/frozen compiler/final M16 qualification pending',compiler_sha256=sha(compiler),sources={str(p.relative_to(ROOT)):sha(p) for p in sources},checks=[],products={})
	def run(command,contains='',env=None):
		assert sha(compiler)==receipt['compiler_sha256'];p=subprocess.run(list(map(str,command)),text=True,capture_output=True,cwd=work,timeout=120,env=dict(os.environ,CCACHE_DISABLE='1',G_DEBUG='fatal-warnings',PYTHONDONTWRITEBYTECODE='1',**(env or {})));receipt['checks'].append(dict(command=list(map(str,command)),exit=p.returncode,stdout=p.stdout,stderr=p.stderr));(work/'checks.json').write_text(json.dumps(receipt,indent=2)+'\n');assert p.returncode==0 and contains in p.stdout+p.stderr,receipt['checks'][-1];return p.stdout
	def memory(client):run(['valgrind','--vgdb=no','--default-suppressions=no','--leak-check=full','--show-leak-kinds=definite,indirect,possible','--errors-for-leak-kinds=definite,indirect,possible','--error-exitcode=99',client],contains='ERROR SUMMARY: 0 errors')
	flags=['-std=gnu11','-Wall','-Wextra','-Werror','-pthread'];includes=shlex.split(run(['pkg-config','--cflags','gobject-2.0']));libs=shlex.split(run(['pkg-config','--libs','gobject-2.0']))
	for native_level in '012':
		unit=work/('producer-O'+native_level);unit.mkdir();source=unit/'implementation.astra';source.write_bytes((here/'gobject-unit.astra').read_bytes());run([compiler,'-O'+native_level,'-c','--module','SharedUnit16','--native-export','SharedUnit16.Session','--native-export','SharedUnit16.Fault','--emit-interface',unit/'session.asti',source,'-o',unit/'session.o']);source.unlink();anchor=unit/'adapter.astra';anchor.write_text('int anchor(){return 0;}\n');header=run([compiler,'--import-module',unit/'session.asti','--emit-gobject-header',anchor]);adapter=unit/'adapter.c';adapter.write_text(run([compiler,'--import-module',unit/'session.asti','--emit-gobject-source',anchor]));assert not source.exists() and 'this.raw' not in adapter.read_text()
		for bridge_level in ('1' if native_level=='1' else '02'):
			sdk=work/('native'+native_level+'-bridge'+bridge_level);inc=sdk/'include';lib=sdk/'lib';inc.mkdir(parents=True);lib.mkdir();(inc/'session.h').write_text(header);library=lib/'libopaque16.so'
			run(['cc',*flags,'-O'+bridge_level,'-fPIC','-shared','-Wl,-z,defs','-Wl,-soname,libopaque16.so',*includes,adapter,here/'gobject-unit-support.c',ROOT/'lib/runtime/interop/foreign-14.c',unit/'session.o',*libs,'-o',library]);client=sdk/'client';run(['cc',*flags,'-O2',*includes,here/'gobject-unit-client.c','-L'+str(lib),'-Wl,-rpath,$ORIGIN/lib','-lopaque16',*libs,'-o',client]);run([client],contains='PASS opaque shared C and GObject views');
			if (native_level,bridge_level) in [('0','0'),('2','2')]:memory(client)
			environment=dict(LD_LIBRARY_PATH=str(lib),GI_TYPELIB_PATH=str(sdk));gir=sdk/'Opaque16-1.0.gir';typelib=sdk/'Opaque16-1.0.typelib';run(['g-ir-scanner','--no-libtool','--namespace=Opaque16','--nsversion=1.0','--include=GObject-2.0','--identifier-prefix=Opaque16','--symbol-prefix=opaque16','--library=opaque16','--library-path='+str(lib),'--c-include=session.h','--warn-all','--warn-error','--output='+str(gir),'--pkg=gobject-2.0','-I'+str(inc),inc/'session.h'],env=environment);run(['g-ir-compiler',gir,'--output='+str(typelib)]);run(['python3',here/'gobject-unit-gi.py',library],contains='PASS opaque scanned GI',env=environment)
			generated=sdk/'generated';run(['python3',importer,'--profile',here/'gobject-unit-profile.json','--gir',gir,'--output',generated]);run(['python3',importer,'--profile',here/'gobject-unit-profile.json','--gir',gir,'--verify',generated]);consumer=sdk/'consumer.astra';consumer.write_text((here/'gobject-unit-roundtrip.astra.in').read_text().replace('@BINDINGS@',(generated/'bindings.astra').read_text()));obj=sdk/'consumer.o';run([compiler,'-O'+native_level,'-c',consumer,'-o',obj]);imports=sdk/'imports.c';imports.write_text(run([compiler,'--emit-gobject-source',consumer]));roundtrip=sdk/'roundtrip';run(['cc',*flags,'-O'+bridge_level,*includes,'-I'+str(inc),imports,here/'gobject-unit-roundtrip-client.c',obj,'-L'+str(lib),'-Wl,-rpath,$ORIGIN/lib','-lopaque16',*libs,'-o',roundtrip]);run([roundtrip],contains='PASS opaque SDK GIR imported native algorithms');
			if (native_level,bridge_level) in [('0','0'),('2','2')]:memory(roundtrip)
			receipt['products'][sdk.name]={str(p.relative_to(sdk)):sha(p) for p in [inc/'session.h',library,client,gir,typelib,generated/'bindings.astra',generated/'contract.json',consumer,obj,imports,roundtrip]}
	receipt['status']='OPAQUE_SHARED_GOBJECT_SDK_PASS';(work/'checks.json').write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps(dict(status=receipt['status'],commands=len(receipt['checks']),receipt=str(work/'checks.json'))))
if __name__=='__main__':main(*sys.argv[1:])
